def budget(self, user_id: str) -> Optional[Decimal]:
    # Per-user override takes precedence; None means unlimited.
    if user_id in self._overrides:
        return self._overrides[user_id]
    # Otherwise return role default (may be None for unlimited).
    return ROLE_BUDGETS[self.get(user_id).role]

def spent(self, user_id: str, month: str) -> Decimal:
    # Sum cost of entries for the given user and month.
    return sum((e.cost for e in self.entries if e.user_id == user_id and e.month == month), Decimal("0"))

def top_spenders(self, month: str, n: int) -> List[Tuple[str, Decimal]]:
    # Compute total cost per user for the month, omit zero-cost users.
    totals: Dict[str, Decimal] = {}
    for e in self.entries:
        if e.month != month:
            continue
        totals.setdefault(e.user_id, Decimal("0"))
        totals[e.user_id] += e.cost
    # Remove zero cost entries
    filtered = [(uid, cost) for uid, cost in totals.items() if cost != Decimal("0")]
    # Sort by cost descending, then user_id ascending
    filtered.sort(key=lambda x: (-x[1], x[0]))
    return filtered[:n]

